struct vector3d
{
  float x, y, z;
  void normalize();
};

inline float dot(const vector3d &a, const vector3d &b)
{
  return a.x*b.x + a.y*b.y + a.z*b.z;
}

inline vector3d operator-(const vector3d &v)
{
  vector3d r = { -v.x, -v.y, -v.z };
  return r;
}

struct po
{
  vector3d non_affine_slow_xform(const vector3d &) const;
};

struct entity
{
  char pad[80];
  po *abs_po;
  po &get_abs_po() { return *abs_po; }
};

class kellyslater_controller
{
  char pad[484];
  bool goofy;
public:
  bool IsGoofy(void) { return goofy; }
};

class game
{
  char pad[552];
  int beachid;
public:
  int get_beach_id(void) { return beachid; }
};

struct BeachData
{
  char pad0[208];
  int bdir;
  char pad1[320];
};

extern const vector3d ZVEC;
extern game *g_game_ptr;
extern BeachData BeachDataArray[];

enum {
  WIP_LOW_AIR_FOR,
  WIP_LOW_AIR_BACK,
  WIP_LOW_AIR_RIGHT,
  WIP_LOW_AIR_LEFT,
  WIP_LOW_AIR_FOR_RIGHT,
  WIP_LOW_AIR_FOR_LEFT,
  WIP_LOW_AIR_BOT_RIGHT,
  WIP_LOW_AIR_BOT_LEFT,
  WIP_LOW_HIT_BY_LIP,
  WIP_LOW_STUMBLE_BACK,
  WIP_LOW_LIE_FOR,
  WIP_LOW_LIE_FLAT,
  WIP_TAKE_OFF_FLAT,
  WIP_HIT_BY_CEILING_LEFT,
  WIP_HIT_BY_CEILING_RIGHT,
  WIP_HIT_BY_CEILING_FOR,
  WIP_HIT_BY_CEILING_BACK
};

class SurfBoardObjectClass
{
  char pad0[2516];
  entity *my_board;
  entity *my_board_model;
  kellyslater_controller *ksctrl;
  char pad1[112];
  int wipeout_type;
  char pad2[92];
  vector3d lip_vec;
public:
  vector3d GetForwardDir(void) { return my_board->get_abs_po().non_affine_slow_xform(ZVEC); }
  int CalculateCeilingWipeout(void);
};

int SurfBoardObjectClass::CalculateCeilingWipeout(void)
{
	vector3d bdir = GetForwardDir();
	bdir.y = 0.0f;
	bdir.normalize();
	float cosine = dot(lip_vec, bdir);
	float cosine2 = dot(bdir, -ZVEC);
	int current_beach = g_game_ptr->get_beach_id ();
    int negative = BeachDataArray[current_beach].bdir;
	if (cosine >= 0.707f)
	{
		if (negative)
		{
			if (ksctrl->IsGoofy())
				wipeout_type = WIP_HIT_BY_CEILING_RIGHT;
			else
				wipeout_type = WIP_HIT_BY_CEILING_LEFT;
		}
		else
		{
			if (ksctrl->IsGoofy())
				wipeout_type = WIP_HIT_BY_CEILING_LEFT;
			else
				wipeout_type = WIP_HIT_BY_CEILING_RIGHT;
		}
	}
	else if (cosine < -0.707f)
	{
		if (negative)
		{
			if (ksctrl->IsGoofy())
				wipeout_type = WIP_HIT_BY_CEILING_LEFT;
			else
				wipeout_type = WIP_HIT_BY_CEILING_RIGHT;
		}
		else
		{
			if (ksctrl->IsGoofy())
				wipeout_type = WIP_HIT_BY_CEILING_RIGHT;
			else
				wipeout_type = WIP_HIT_BY_CEILING_LEFT;
		}
	}
	else if (cosine2 >= 0.707f)
		wipeout_type = WIP_HIT_BY_CEILING_FOR;
	else
		wipeout_type = WIP_HIT_BY_CEILING_BACK;

	return wipeout_type;
}
